121	func TestRetryTransport_CapsServerRetryAfter(t *testing.T) {
122		t.Parallel()
123	
124		tests := []struct {
125			name       string
126			retryAfter string
127			wantSleep  time.Duration
128		}{
129			{name: "beyond cap", retryAfter: "3600", wantSleep: time.Minute},
130			{name: "overflowing seconds", retryAfter: "9999999999999999", wantSleep: time.Minute},
131			{name: "within cap beyond MaxDelay", retryAfter: "30", wantSleep: 30 * time.Second},
132		}
133	
134		for _, tt := range tests {
135			t.Run(tt.name, func(t *testing.T) {
136				t.Parallel()
137	
138				var calls int
139				next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
140					calls++
141					h := make(http.Header)
142					if calls == 1 {
143						h.Set("Retry-After", tt.retryAfter)
144						return &http.Response{
145							StatusCode: 429,
146							Header:     h,
147							Body:       io.NopCloser(strings.NewReader("")),
148							Request:    req,
149						}, nil
150					}
151					return &http.Response{
152						StatusCode: 200,
153						Header:     h,
154						Body:       io.NopCloser(strings.NewReader("")),
155						Request:    req,
156					}, nil
157				})
158	
159				var sleeps []time.Duration
160				policy := DefaultRetryPolicy()
161				policy.Jitter = func(d time.Duration) time.Duration { return d }
162	
163				rt := newRetryTransport(next, policy, retryTransportOptions{
164					sleep: func(_ context.Context, d time.Duration) error {
165						sleeps = append(sleeps, d)
166						return nil
167					},
168					now: func() time.Time { return time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC) },
169				})
170	
171				req, _ := http.NewRequestWithContext(context.Background(), http.MethodPost, "https://example.test", nil)
172				resp, err := rt.RoundTrip(req)
173				if err != nil {
174					t.Fatalf("unexpected error: %v", err)
175				}
176				_ = resp.Body.Close()
177	
178				if len(sleeps) != 1 || sleeps[0] != tt.wantSleep {
179					t.Fatalf("expected sleep %s, got %v", tt.wantSleep, sleeps)
180				}
181			})
182		}
183	}
