355	func TestRetryHelpers(t *testing.T) {
356		t.Parallel()
357	
358		for _, method := range []string{
359			http.MethodGet,
360			http.MethodHead,
361			http.MethodPut,
362			http.MethodDelete,
363			http.MethodOptions,
364			http.MethodTrace,
365		} {
366			if !isIdempotentMethod(method) {
367				t.Fatalf("expected %s to be idempotent", method)
368			}
369		}
370		for _, method := range []string{http.MethodPost, http.MethodPatch, "CUSTOM"} {
371			if isIdempotentMethod(method) {
372				t.Fatalf("expected %s to be non-idempotent", method)
373			}
