375	
376		if got := fullJitter(0); got != 0 {
377			t.Fatalf("fullJitter(0) = %s, want 0", got)
378		}
379		if got := fullJitter(-time.Second); got != 0 {
380			t.Fatalf("fullJitter(-1s) = %s, want 0", got)
381		}
382		for i := 0; i < 20; i++ {
383			if got := fullJitter(10 * time.Millisecond); got < 0 || got >= 10*time.Millisecond {
384				t.Fatalf("fullJitter out of range: %s", got)
