404	func TestSanitizeRetryPolicy_ClampsInvalidValues(t *testing.T) {
405		t.Parallel()
406	
407		policy := sanitizeRetryPolicy(RetryPolicy{
408			MaxAttempts: -3,
409			BaseDelay:   -time.Second,
410			MaxDelay:    0,
411			Jitter:      nil,
412		})
413	
414		if policy.MaxAttempts != 1 {
415			t.Fatalf("expected max attempts 1, got %d", policy.MaxAttempts)
416		}
417		if policy.BaseDelay != 0 {
418			t.Fatalf("expected base delay 0, got %s", policy.BaseDelay)
419		}
420		if policy.MaxDelay != 0 {
421			t.Fatalf("expected max delay 0, got %s", policy.MaxDelay)
422		}
423		if policy.Jitter == nil {
424			t.Fatalf("expected default jitter")
425		}
426		if got := policy.Jitter(3 * time.Second); got != 3*time.Second {
427			t.Fatalf("unexpected default jitter result: %s", got)
428		}
429	
430		policy = sanitizeRetryPolicy(RetryPolicy{
431			MaxAttempts: 2,
432			BaseDelay:   time.Second,
433			MaxDelay:    -time.Second,
434			Jitter:      func(d time.Duration) time.Duration { return d / 2 },
435		})
436		if policy.MaxDelay != time.Second {
437			t.Fatalf("expected max delay to default to base delay, got %s", policy.MaxDelay)
438		}
439		if got := policy.Jitter(4 * time.Second); got != 2*time.Second {
440			t.Fatalf("unexpected custom jitter result: %s", got)
441		}
442	}
