2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"net/http"
11		"net/url"
12		"strings"
13		"time"
14	)
15	
16	type RawClient struct {
17		baseURL    *url.URL
18		httpClient *http.Client
19	}
20	
21	func NewRawClient(baseURL string, httpClient *http.Client) (*RawClient, error) {
22		if httpClient == nil {
23			httpClient = http.DefaultClient
24		}
25		u, err := url.Parse(baseURL)
26		if err != nil {
27			return nil, fmt.Errorf("parse base url: %w", err)
28		}
29		if u.Scheme == "" || u.Host == "" {
30			return nil, errors.New("base url must include scheme and host")
31		}
32		u.Path = strings.TrimSuffix(u.Path, "/")
33	
34		return &RawClient{
35			baseURL:    u,
36			httpClient: httpClient,
37		}, nil
38	}
39	
40	func (c *RawClient) Do(ctx context.Context, method, path string, query url.Values, body any, out any, opts ...RequestOption) error {
41		if c == nil {
42			return errors.New("nil RawClient")
43		}
44	
45		ctx, editors := ApplyRequestOptions(ctx, opts...)
46	
47		u := *c.baseURL
48		u.Path = strings.TrimSuffix(u.Path, "/") + "/" + strings.TrimPrefix(path, "/")
49		if query != nil {
50			q := u.Query()
51			for k, vs := range query {
52				for _, v := range vs {
53					q.Add(k, v)
54				}
55			}
56			u.RawQuery = q.Encode()
57		}
58	
59		var reqBody io.Reader
60		if body != nil {
61			switch b := body.(type) {
62			case io.Reader:
63				reqBody = b
64			default:
65				buf, err := json.Marshal(b)
66				if err != nil {
67					return fmt.Errorf("encode json body: %w", err)
68				}
69				reqBody = bytes.NewReader(buf)
70			}
71		}
72	
73		req, err := http.NewRequestWithContext(ctx, method, u.String(), reqBody)
74		if err != nil {
75			return fmt.Errorf("build request: %w", err)
76		}
77	
78		req.Header.Set("Accept", "application/json")
79		if body != nil {
80			if _, ok := body.(io.Reader); !ok {
81				req.Header.Set("Content-Type", "application/json")
82			}
83		}
84	
85		for _, editor := range editors {
86			if editor == nil {
87				continue
88			}
89			if err := editor(ctx, req); err != nil {
90				return err
91			}
92		}
93	
94		resp, err := c.httpClient.Do(req)
95		if err != nil {
96			return err
97		}
98		defer resp.Body.Close()
99	
100		respBody, err := io.ReadAll(resp.Body)
101		if err != nil {
102			return fmt.Errorf("read response: %w", err)
103		}
104	
105		if resp.StatusCode < 200 || resp.StatusCode > 299 {
106			if resp.StatusCode == http.StatusTooManyRequests {
107				return RateLimitErrorFromResponse(resp, respBody, time.Now())
108			}
109			return APIErrorFromResponse(resp, respBody)
110		}
111	
112		if out == nil || len(respBody) == 0 {
113			return nil
114		}
115		if err := json.Unmarshal(respBody, out); err != nil {
116			return fmt.Errorf("decode response json: %w", err)
117		}
118		return nil
119	}
