325	func (s *CallLogsService) Create(ctx context.Context, opts ...CreateCallLogOption) (*CallLog, error) {
326		cfg := newCreateCallLogOptions(opts)
327		ctx, editors := pipedrive.ApplyRequestOptions(ctx, cfg.requestOptions...)
328	
329		if cfg.payload.toPhone == nil || cfg.payload.outcome == nil || cfg.payload.startTime == nil || cfg.payload.endTime == nil {
330			return nil, fmt.Errorf("to phone number, outcome, start time, and end time are required")
331		}
332	
333		body, err := json.Marshal(cfg.payload.toMap())
334		if err != nil {
335			return nil, fmt.Errorf("encode request: %w", err)
336		}
337	
338		resp, err := s.client.gen.AddCallLogWithBody(ctx, "application/json", bytes.NewReader(body), toRequestEditors(editors)...)
339		if err != nil {
340			return nil, err
341		}
342		defer resp.Body.Close()
343		respBody, err := io.ReadAll(resp.Body)
344		if err != nil {
345			return nil, fmt.Errorf("read response: %w", err)
346		}
347		if resp.StatusCode < 200 || resp.StatusCode > 299 {
348			return nil, errorFromResponse(resp, respBody)
349		}
350	
351		var payload struct {
352			Data *CallLog `json:"data"`
353		}
354		if err := json.Unmarshal(respBody, &payload); err != nil {
355			return nil, fmt.Errorf("decode response: %w", err)
356		}
357		if payload.Data == nil {
358			return nil, fmt.Errorf("missing call log data in response")
359		}
360		return payload.Data, nil
361	}
