1	package pipedrive
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"math"
7		"net/http"
8		"strconv"
9		"time"
10	)
11	
12	type APIError struct {
13		Status    int
14		Code      string
15		Message   string
16		Body      []byte
17		RequestID string
18	}
19	
20	func (e *APIError) Error() string {
21		if e == nil {
22			return "pipedrive: <nil>"
23		}
24		if e.Code != "" && e.Message != "" {
25			return fmt.Sprintf("pipedrive: http %d %s: %s", e.Status, e.Code, e.Message)
26		}
27		if e.Message != "" {
28			return fmt.Sprintf("pipedrive: http %d: %s", e.Status, e.Message)
29		}
30		if e.Code != "" {
31			return fmt.Sprintf("pipedrive: http %d %s", e.Status, e.Code)
32		}
33		return fmt.Sprintf("pipedrive: http %d", e.Status)
34	}
35	
36	type RateLimitError struct {
37		*APIError
38	
39		RetryAfter time.Duration
40		Limit      int
41		Remaining  int
42		Reset      time.Time
43	}
44	
45	func (e *RateLimitError) Unwrap() error { return e.APIError }
46	
47	func (e *RateLimitError) Error() string {
48		if e == nil || e.APIError == nil {
49			return "pipedrive: rate limit"
50		}
51		if e.RetryAfter > 0 {
52			return fmt.Sprintf("%s (retry after %s)", e.APIError.Error(), e.RetryAfter)
53		}
54		return e.APIError.Error()
55	}
56	
57	type ResponseTooLargeError struct {
58		Limit int64
59	}
60	
61	func (e *ResponseTooLargeError) Error() string {
62		if e == nil {
63			return "pipedrive: response too large"
64		}
65		return fmt.Sprintf("pipedrive: response exceeds %d bytes", e.Limit)
66	}
67	
68	type pipedriveErrorPayload struct {
69		Code      string `json:"code"`
70		Message   string `json:"message"`
71		Error     string `json:"error"`
72		ErrorInfo string `json:"error_info"`
73	}
74	
75	func APIErrorFromResponse(resp *http.Response, body []byte) *APIError {
76		err := &APIError{
77			Status:    resp.StatusCode,
78			Body:      body,
79			RequestID: resp.Header.Get("X-Request-Id"),
80		}
81	
82		var payload pipedriveErrorPayload
83		if json.Unmarshal(body, &payload) == nil {
84			if payload.Code != "" {
85				err.Code = payload.Code
86			}
87			switch {
88			case payload.Message != "":
89				err.Message = payload.Message
90			case payload.Error != "":
91				err.Message = payload.Error
92			}
93		}
94	
95		return err
96	}
97	
98	func RateLimitErrorFromResponse(resp *http.Response, body []byte, now time.Time) *RateLimitError {
99		apiErr := APIErrorFromResponse(resp, body)
100		rl := &RateLimitError{
101			APIError: apiErr,
102		}
103	
104		rl.RetryAfter = parseRetryAfter(resp.Header.Get("Retry-After"), now)
105		rl.Limit = parseIntHeader(resp.Header.Get("X-RateLimit-Limit"))
106		rl.Remaining = parseIntHeader(resp.Header.Get("X-RateLimit-Remaining"))
107		rl.Reset = parseResetHeader(resp.Header.Get("X-RateLimit-Reset"))
108	
109		return rl
110	}
111	
112	func parseRetryAfter(value string, now time.Time) time.Duration {
113		if value == "" {
114			return 0
115		}
116		if secs, err := strconv.Atoi(value); err == nil && secs >= 0 {
117			// Saturate instead of letting secs*time.Second wrap int64.
118			if int64(secs) > math.MaxInt64/int64(time.Second) {
119				return time.Duration(math.MaxInt64)
120			}
121			return time.Duration(secs) * time.Second
122		}
123		if t, err := http.ParseTime(value); err == nil {
124			if t.After(now) {
125				return t.Sub(now)
126			}
127			return 0
128		}
129		return 0
130	}
131	
132	func parseIntHeader(value string) int {
133		if value == "" {
134			return 0
135		}
136		n, err := strconv.Atoi(value)
137		if err != nil {
138			return 0
139		}
140		return n
141	}
142	
143	func parseResetHeader(value string) time.Time {
144		if value == "" {
145			return time.Time{}
146		}
147	
148		if unix, err := strconv.ParseInt(value, 10, 64); err == nil {
149			if unix > 1_000_000_000_000 {
150				return time.UnixMilli(unix).UTC()
151			}
152			return time.Unix(unix, 0).UTC()
153		}
154	
155		if t, err := http.ParseTime(value); err == nil {
156			return t.UTC()
157		}
158	
159		return time.Time{}
160	}
