78	func (p *Product) UnmarshalJSON(data []byte) error {
79		if p == nil {
80			return fmt.Errorf("v2.Product: UnmarshalJSON on nil receiver")
81		}
82	
83		type productAlias Product
84		var aux struct {
85			productAlias
86			Category json.RawMessage `json:"category"`
87		}
88		if err := json.Unmarshal(data, &aux); err != nil {
89			return fmt.Errorf("v2.Product: decode: %w", err)
90		}
91	
92		*p = Product(aux.productAlias)
93	
94		if len(aux.Category) == 0 {
95			return nil
96		}
97		category := bytes.TrimSpace(aux.Category)
98		if len(category) == 0 || bytes.Equal(category, []byte("null")) {
99			p.CategoryName = nil
100			return nil
101		}
102	
103		var numeric float64
104		if err := json.Unmarshal(category, &numeric); err == nil {
105			p.Category = numeric
106			p.CategoryName = nil
107			return nil
108		}
109	
110		var label string
111		if err := json.Unmarshal(category, &label); err == nil {
112			p.CategoryName = &label
113			return nil
114		}
115	
116		return fmt.Errorf("v2.Product: invalid category value %q", string(category))
117	}
