1	package pipedrive
2	
3	import (
4		"context"
5		"io"
6		"net/http"
7	)
8	
9	const defaultMaxResponseSize int64 = 64 << 20
10	
11	// errorResponseBodyLimit caps how much of a non-2xx response body is kept
12	// for error reporting. Unlike the success-path limit, exceeding it is not
13	// an error: reads simply stop at the cap. Per-request overrides do not
14	// apply — a hostile or broken server must never make the client buffer an
15	// unbounded error payload.
16	const errorResponseBodyLimit int64 = 1 << 20
17	
18	type responseSizeLimitOption struct {
19		set       bool
20		limit     int64
21		unlimited bool
22	}
23	
24	type responseSizeLimitKey struct{}
25	
26	func withResponseSizeLimit(ctx context.Context, opt responseSizeLimitOption) context.Context {
27		return context.WithValue(ctx, responseSizeLimitKey{}, opt)
28	}
29	
30	func responseSizeLimitFromContext(ctx context.Context) (responseSizeLimitOption, bool) {
31		opt, ok := ctx.Value(responseSizeLimitKey{}).(responseSizeLimitOption)
32		return opt, ok
33	}
34	
35	func normalizeResponseSizeLimit(limit int64) int64 {
36		switch {
37		case limit < 0:
38			return -1
39		case limit == 0:
40			return defaultMaxResponseSize
41		default:
42			return limit
43		}
44	}
45	
46	func effectiveResponseSizeLimit(ctx context.Context, defaultLimit int64) int64 {
47		limit := normalizeResponseSizeLimit(defaultLimit)
48	
49		override, ok := responseSizeLimitFromContext(ctx)
50		if !ok || !override.set {
51			return limit
52		}
53		if override.unlimited {
54			return -1
55		}
56		return normalizeResponseSizeLimit(override.limit)
57	}
58	
59	type responseLimitTransport struct {
60		next         http.RoundTripper
61		defaultLimit int64
62	}
63	
64	func newResponseLimitTransport(next http.RoundTripper, defaultLimit int64) http.RoundTripper {
65		if next == nil {
66			next = http.DefaultTransport
67		}
68		return &responseLimitTransport{
69			next:         next,
70			defaultLimit: defaultLimit,
71		}
72	}
73	
74	func (t *responseLimitTransport) RoundTrip(req *http.Request) (*http.Response, error) {
75		resp, err := t.next.RoundTrip(req)
76		if err != nil || resp == nil || resp.Body == nil {
77			return resp, err
78		}
79		if resp.StatusCode < 200 || resp.StatusCode > 299 {
80			resp.Body = &truncatingReadCloser{
81				reader: io.LimitReader(resp.Body, errorResponseBodyLimit),
82				closer: resp.Body,
83			}
84			return resp, nil
85		}
86	
87		limit := effectiveResponseSizeLimit(req.Context(), t.defaultLimit)
88		if limit < 0 {
89			return resp, nil
90		}
91	
92		resp.Body = &responseLimitReadCloser{
93			body:      resp.Body,
94			limit:     limit,
95			remaining: limit,
96		}
97		return resp, nil
98	}
99	
100	type responseLimitReadCloser struct {
101		body      io.ReadCloser
102		limit     int64
103		remaining int64
104	}
105	
106	func (r *responseLimitReadCloser) Read(p []byte) (int, error) {
107		if len(p) == 0 {
108			return r.body.Read(p)
109		}
110		if r.remaining <= 0 {
111			var probe [1]byte
112			n, err := r.body.Read(probe[:])
113			switch {
114			case n == 0 && err == io.EOF:
115				return 0, io.EOF
116			case n > 0 || err == nil:
117				return 0, &ResponseTooLargeError{Limit: r.limit}
118			default:
119				return 0, err
120			}
121		}
122	
123		if int64(len(p)) > r.remaining {
124			p = p[:int(r.remaining)]
125		}
126	
127		n, err := r.body.Read(p)
128		r.remaining -= int64(n)
129		return n, err
130	}
131	
132	func (r *responseLimitReadCloser) Close() error {
133		return r.body.Close()
134	}
135	
136	type truncatingReadCloser struct {
137		reader io.Reader
138		closer io.Closer
139	}
140	
141	func (t *truncatingReadCloser) Read(p []byte) (int, error) {
142		return t.reader.Read(p)
143	}
144	
145	func (t *truncatingReadCloser) Close() error {
146		return t.closer.Close()
147	}
