11	func TestNewHTTPClient_MiddlewareOrder(t *testing.T) {
12		t.Parallel()
13	
14		var calls []string
15	
16		base := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
17			calls = append(calls, "base")
18			return &http.Response{
19				StatusCode: 200,
20				Header:     make(http.Header),
21				Body:       io.NopCloser(strings.NewReader("")),
22				Request:    req,
23			}, nil
24		})
25	
26		mw1 := func(next http.RoundTripper) http.RoundTripper {
27			return roundTripperFunc(func(req *http.Request) (*http.Response, error) {
28				calls = append(calls, "mw1")
29				return next.RoundTrip(req)
30			})
31		}
32		mw2 := func(next http.RoundTripper) http.RoundTripper {
33			return roundTripperFunc(func(req *http.Request) (*http.Response, error) {
34				calls = append(calls, "mw2")
35				return next.RoundTrip(req)
36			})
37		}
38	
39		httpClient := NewHTTPClient(Config{
40			HTTPClient:  &http.Client{Transport: base},
41			Middleware:  []Middleware{mw1, mw2},
42			RetryPolicy: &RetryPolicy{MaxAttempts: 1},
43		})
44	
45		req, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "https://example.test", nil)
46		resp, err := httpClient.Transport.RoundTrip(req)
47		if err != nil {
48			t.Fatalf("unexpected error: %v", err)
49		}
50		_ = resp.Body.Close()
51	
52		want := []string{"mw1", "mw2", "base"}
53		if len(calls) != len(want) {
54			t.Fatalf("unexpected call count: got %v want %v", calls, want)
55		}
56		for i := range want {
57			if calls[i] != want[i] {
58				t.Fatalf("unexpected order: got %v want %v", calls, want)
59			}
60		}
61	}
