	applyAddFile(*addFileOptions)
}

type addFileOptions struct {
	fields         map[string]string
	requestOptions []pipedrive.RequestOption
}

type addFileOptionFunc func(*addFileOptions)

func (f addFileOptionFunc) applyAddFile(cfg *addFileOptions) { f(cfg) }

func WithAddFileRequestOptions(opts ...pipedrive.RequestOption) AddFileOption {
	return addFileOptionFunc(func(cfg *addFileOptions) {
		cfg.requestOptions = append(cfg.requestOptions, opts...)
	})
}

func withAddFileField(key, value string) AddFileOption {
	return addFileOptionFunc(func(cfg *addFileOptions) {
		if cfg.fields == nil {
			cfg.fields = make(map[string]string)
		}
		cfg.fields[key] = value
	})
}

func WithAddFileDealID(id DealID) AddFileOption       { return withAddFileField("deal_id", strconv.FormatInt(int64(id), 10)) }
func WithAddFilePersonID(id PersonID) AddFileOption    { return withAddFileField("person_id", strconv.FormatInt(int64(id), 10)) }
func WithAddFileOrgID(id OrganizationID) AddFileOption { return withAddFileField("org_id", strconv.FormatInt(int64(id), 10)) }
func WithAddFileActivityID(id ActivityID) AddFileOption {
	return withAddFileField("activity_id", strconv.FormatInt(int64(id), 10))
}
func WithAddFileLeadID(id LeadID) AddFileOption       { return withAddFileField("lead_id", string(id)) }
func WithAddFileProductID(id ProductID) AddFileOption  { return withAddFileField("product_id", strconv.FormatInt(int64(id), 10)) }
func WithAddFileProjectID(id ProjectID) AddFileOption  { return withAddFileField("project_id", strconv.FormatInt(int64(id), 10)) }

func newAddFileOptions(opts []AddFileOption) addFileOptions {
	var cfg addFileOptions
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		opt.applyAddFile(&cfg)
	}
	return cfg
}

